/* Crea los botones de las redes sociales del pie de pagina. */
function crearRedesSociales() {
  var html = "";
  for (var i = 0; i < REDES.length; i++) {
    var red = REDES[i];
    var url = red.url;
    if (red.icono === "whatsapp") {
      url = enlaceWhatsApp();
    }
    html = html + `
        <a href="${url}" target="_blank" rel="noopener" aria-label="${red.nombre}" data-icono="${red.icono}"></a>`;
  }
  return html;
}

function crearOpcionesArea() {
  var html = `<option value="" disabled selected data-i18n="formulario.area.vacia">Seleccione un área</option>`;
  for (var i = 0; i < AREAS.length; i++) {
    html = html + `<option value="${AREAS[i].valor}" data-i18n="areas.${i}">${AREAS[i].texto}</option>`;
  }
  return html;
}

/* Crea los campos de texto del formulario.
   Los que tienen "mitad: true" van de a dos en una fila: por eso se
   acumulan en una variable aparte y se sueltan de dos en dos. */
function crearCamposFormulario() {
  var html = "";
  var pares = "";

  for (var i = 0; i < CAMPOS.length; i++) {
    var campo = CAMPOS[i];
    var bloque = "";

    if (campo.mitad) {
      bloque = `
                <div>
                  <label for="${campo.id}" data-i18n="${campo.clave}">${campo.etiqueta} ${asterisco(campo.requerido)}</label>
                  <input type="${campo.tipo}" id="${campo.id}" name="${campo.id}"
                         placeholder="${campo.placeholder}" ${atributoObligatorio(campo.requerido)}>
                </div>`;
    } else {
      var ayudaHtml = "";
      if (campo.ayuda) {
        ayudaHtml = `<span class="ayuda" data-i18n="${campo.clave}.ayuda">${campo.ayuda}</span>`;
      }

      bloque = `
              <div class="campo">
                <label for="${campo.id}" data-i18n="${campo.clave}">${campo.etiqueta} ${asterisco(campo.requerido)}</label>
                <input type="${campo.tipo}" id="${campo.id}" name="${campo.id}"
                       placeholder="${campo.placeholder}" ${atributoObligatorio(campo.requerido)}>
                ${ayudaHtml}
              </div>`;
    }

    if (campo.mitad) {
      pares = pares + bloque;
    } else {
      html = html + bloque;
    }
  }

  return `
              <div class="fila-doble">
                ${pares}
              </div>
              ${html}`;
}


