/* La seccion "Nuestra Historia": el grupo y su historia.
   "completo" = true para la pagina Nosotros; false es el resumen
   del inicio. */
function crearHistoria(completo) {
  if (!completo) {
    return crearHistoriaResumen();
  }

  return `
  <section class="seccion seccion-gris" id="historia">
    <div class="contenedor">

      <h2 class="titulo-seccion" data-i18n="historia.titulo">Nuestra Historia</h2>
      <div class="linea-azul"></div>

      <div class="dos-columnas">

        <div class="col-texto">
          <p data-i18n="historia.p1">
            Somos un grupo consultor dinámico, compuesto por las firmas
            <strong>Montes Abogados Asociados S.A.S.</strong> y
            <strong>Montes &amp; Warren S.A.S.</strong>, especializado en la prestación
            de servicios de asesoría legal y de negocios, con énfasis en la atención a empresas.
          </p>
          <p data-i18n="historia.p2">
            Tras haber consolidado experiencia durante 10 años en la prestación de servicios
            de consultoría especializada y litigio, desde Montes Abogados Asociados S.A.S. surge
            Montes &amp; Warren S.A.S., una firma proyectada, específicamente para la atención
            de clientes extranjeros que buscan establecer sus inversiones en Colombia, o para
            la expansión hacia el extranjero de negocios nacionales.
          </p>
          <p data-i18n="historia.p3">
            Montes Abogados y Montes &amp; Warren trabajan de manera conjunta para la atención
            de las necesidades de clientes en Colombia, y Montes &amp; Warren consolidó en el
            año 2019 presencia en España, a través de su filial Montes &amp; Warren S.L.U.,
            creada para la atención de clientes de la firma en la Unión Europea.
          </p>
        </div>

        <div class="col-azul">
          <h3 data-i18n="historia.panel.titulo">Montes Group</h3>
          <ul>
            <li data-i18n="historia.panel.1">10 años de experiencia en consultoría y litigio</li>
            <li data-i18n="historia.panel.2">Dos firmas: Montes Abogados y Montes &amp; Warren</li>
            <li data-i18n="historia.panel.3">Presencia en España desde 2019</li>
            <li data-i18n="historia.panel.4">Montes &amp; Warren S.L.U. para la Unión Europea</li>
            <li data-i18n="historia.panel.5">Atención especializada a empresas</li>
            <li data-i18n="historia.panel.6">Relaciones duraderas con nuestros clientes</li>
          </ul>
        </div>

      </div>
    </div>
  </section>`;
}

