/* Devuelve los datos del cliente guardados en el navegador,
   o null si no hay ninguno. */

function leerCliente() {
  try {
    var guardado = localStorage.getItem(CLAVE_CLIENTE);
    if (guardado) {
      return JSON.parse(guardado);
    }
  } catch (error) {
    console.log("No se pudo leer la sesion:", error.message);
  }
  return null;
}




/* Muestra el area "Mi cuenta": si hay cliente, el panel con sus
   datos y el boton de salir; si no, el formulario de ingreso. */

function mostrarPanelCuenta(cliente) {
  var login = document.getElementById("cuentaLogin");
  var panel = document.getElementById("cuentaPanel");

  if (!login || !panel) {
    return;
  }

  if (cliente) {
    login.classList.add("oculto");
    panel.classList.remove("oculto");
    document.getElementById("cuentaUsuario").textContent = cliente.correo + " · " + cliente.telefono;
    mostrarSolicitudes();
  } else {
    login.classList.remove("oculto");
    panel.classList.add("oculto");
  }
}

/* =======================================================
   3b. DATOS QUE PUEDE EDITAR EL ADMINISTRADOR
   -------------------------------------------------------
   El panel de administracion deja un archivo datos.json
   (subido al hosting) y tambien guarda cambios en este
   navegador. Aqui se aplican esos cambios sobre los datos.
   ======================================================= */

/* Aplica sobre el sitio los cambios que hizo el administrador.
   Se van cambiando uno por uno los objetos de datos (SITIO,
   SERVICIOS, EQUIPO, PUBLICACIONES) y al final se vuelve a dibujar
   la pagina para que se vean los cambios. */

function aplicarDatosGuardados(datos) {

  /* Se van tocando uno por uno los objetos de datos del sitio.
     Al final, redibujarPagina() vuelve a pintar la pagina con los
     cambios. */
  if (!datos) {
    return;
  }

  /* Diapositivas del carrusel: solo las que tienen imagen. */
  if (Array.isArray(datos.carrusel)) {
    CARRUSEL.length = 0;
    for (var c = 0; c < datos.carrusel.length; c++) {
      if (datos.carrusel[c] && datos.carrusel[c].imagen) {
        CARRUSEL.push(datos.carrusel[c]);
      }
    }
  }

  if (datos.empresa) {
    if (datos.empresa.nombre) {
      SITIO.nombre = datos.empresa.nombre;
    }
    if (datos.empresa.grupo) {
      SITIO.grupo = datos.empresa.grupo;
    }
    if (datos.empresa.colorMarca) {
      document.documentElement.style.setProperty("--marca", datos.empresa.colorMarca);
    }
    if (datos.empresa.logo) {
      SITIO.logo = datos.empresa.logo;
    }
  }

  if (datos.contacto) {
    for (var clave in datos.contacto) {
      if (datos.contacto.hasOwnProperty(clave)) {
        SITIO[clave] = datos.contacto[clave];
      }
    }
  }

  if (datos.servicios && datos.servicios.length) {
    for (var i = 0; i < SERVICIOS.length; i++) {
      if (datos.servicios[i]) {
        SERVICIOS[i].titulo = datos.servicios[i].titulo;
        SERVICIOS[i].texto = datos.servicios[i].texto;
        SERVICIOS[i].corto = datos.servicios[i].titulo;
      }
    }
  }

  if (datos.publicaciones && datos.publicaciones.length) {
    while (PUBLICACIONES.length > 0) {
      PUBLICACIONES.pop();
    }
    for (var p = 0; p < datos.publicaciones.length; p++) {
      var nueva = datos.publicaciones[p];
      PUBLICACIONES.push({
        titulo: nueva.titulo,  /* el titulo */
        fecha: nueva.fecha,  /* la fecha */
        autora: nueva.autora,  /* quien lo escribe */
        categoria: nueva.categoria,  /* a que categoria pertenece */
        resumen: nueva.resumen,  /* el resumen de dos lineas */
        imagen: nueva.imagen || "",  /* el dibujo de la publicacion */
        pdf: nueva.pdf || ""
      });
    }
  }

  if (datos.equipo && datos.equipo.length) {
    var originales = [];
    for (var k = 0; k < EQUIPO.length; k++) {
      originales.push(EQUIPO[k].sinopsis);
      }

      while (EQUIPO.length > 0) {
        EQUIPO.pop();
      }

      for (var j = 0; j < datos.equipo.length; j++) {
        var persona = datos.equipo[j];
        var sinopsis = persona.sinopsis && persona.sinopsis !== ""
          ? persona.sinopsis
          : (originales[j] ? originales[j] : "");

        EQUIPO.push({
          nombre: persona.nombre,  /* el nombre de la firma */
          cargo: persona.cargo,  /* el puesto que ocupa */
          iniciales: persona.iniciales,  /* las dos letras del monograma */
          linkedin: persona.linkedin || "",  /* el enlace de LinkedIn (si queda vacio, no se muestra el boton) */
          sinopsis: sinopsis
        });
      }
    }
}

/* Vuelve a dibujar la pagina con los datos actuales.
   Se usa cuando el administrador cambia algo y hay que ver el
   resultado sin recargar el navegador. */

function redibujarPagina() {
  var contenedor = document.getElementById("app");
  if (!contenedor) {
    return;
  }
  var pagina = contenedor.getAttribute("data-pagina") || "pagina-montes.html";
  contenedor.innerHTML = construirPagina(pagina);
  iniciarMenu();
  iniciarFormulario();
  iniciarAnimacionesScroll();
}

/* Busca los datos que el administrador guardo en este navegador
   (la clave es "datosMontesSitio") y los aplica al sitio. */

/* Devuelve los datos del sitio. Prioridad:
   1) los guardados en este navegador (vista previa del administrador);
   2) el archivo datos.json publicado junto al sitio (lo ven todos).
   Si no hay ninguno (o se abre como archivo file://), devuelve null. */
function obtenerDatosDelSitio() {
  var local = null;
  try {
    var guardado = localStorage.getItem("datosMontesSitio");
    if (guardado) {
      local = JSON.parse(guardado);
    }
  } catch (error) {
    local = null;
  }
  if (local) {
    return Promise.resolve(local);
  }
  return fetch("datos.json", { cache: "no-store" })
    .then(function (respuesta) {
      return respuesta.ok ? respuesta.json() : null;
    })
    .catch(function () {
      return null;
    });
}

function buscarDatosGuardados(datos) {
  try {
    if (datos) {
      var equipoActualizado = false;

      if (datos && !datos.versionEquipo) {
        if (Array.isArray(datos.equipo) && datos.equipo.length) {
          var tieneLaura = false;
          for (var i = 0; i < datos.equipo.length; i++) {
            if (datos.equipo[i].nombre === "Laura Catalina Urrego Sastre") {
              tieneLaura = true;
              break;
            }
          }

          if (!tieneLaura) {
            for (var j = 0; j < EQUIPO.length; j++) {
              if (EQUIPO[j].nombre === "Laura Catalina Urrego Sastre") {
                datos.equipo.splice(Math.min(4, datos.equipo.length), 0, {
                  nombre: EQUIPO[j].nombre,
                  cargo: EQUIPO[j].cargo,
                  iniciales: EQUIPO[j].iniciales,
                  linkedin: EQUIPO[j].linkedin,
                  sinopsis: EQUIPO[j].sinopsis
                });
                equipoActualizado = true;
                break;
              }
            }
          }
        }

        datos.versionEquipo = 1;
        equipoActualizado = true;
      }

      if (equipoActualizado) {
        try {
          localStorage.setItem("datosMontesSitio", JSON.stringify(datos));
        } catch (error) {
          console.log("No se pudo guardar la actualizacion del equipo:", error.message);
        }
      }

      aplicarDatosGuardados(datos);
      console.log("Cambios del administrador aplicados.");
    }
  } catch (error) {
    console.log("No se pudieron leer los datos guardados:", error.message);
  }

}

/* =======================================================
   4. COMPORTAMIENTO: lo que pasa al hacer clic
   ======================================================= */

/* Menú hamburguesa: abre y cierra en el celular.
   toggle() pone la clase si no esta, o la quita si esta.
   addEventListener significa: "cuando pase esto, haz aquello".
   Aqui: cuando la persona pulse el boton de las tres rayitas,
   se muestra o se esconde la lista de enlaces. */

function iniciarMenu() {
  var boton = document.getElementById("menuBtn");
  var enlaces = document.getElementById("navLinks");

  boton.addEventListener("click", function () {
    enlaces.classList.toggle("abierto");
  });

  var todosLosEnlaces = enlaces.querySelectorAll("a");
  for (var i = 0; i < todosLosEnlaces.length; i++) {
    todosLosEnlaces[i].addEventListener("click", function () {
      enlaces.classList.remove("abierto");
    });
  }

  window.addEventListener("resize", function () {
    if (window.innerWidth > 600) {
      enlaces.classList.remove("abierto");
    }
  });
}

/* Borra los errores rojos del formulario antes de volver a validar.
   Se quitan las clases de error de los campos y los textos que
   habian quedado debajo. */

function limpiarErrores() {
  var campos = document.querySelectorAll(".campo-error");
  for (var i = 0; i < campos.length; i++) {
    campos[i].classList.remove("campo-error");
  }

  var textos = document.querySelectorAll(".texto-error");
  for (var j = 0; j < textos.length; j++) {
    textos[j].remove();
  }
}

/* Guarda la prueba de que la persona autorizo el tratamiento de sus datos.
   Con cada envio queda registrada la fecha y hora, el nombre, el correo,
   que casillas se marcaron y la version de la politica vigente.
   Es lo que la politica de datos exige: "MAA conserva prueba de
   cada autorizacion". */

function guardarPruebaAutorizacion(prueba) {
  try {
    var clave = "pruebasAutorizacionMontes";
    var guardado = localStorage.getItem(clave);
    var lista = guardado ? JSON.parse(guardado) : [];
    lista.push(prueba);
    localStorage.setItem(clave, JSON.stringify(lista));
  } catch (error) {
    console.log("No se pudo guardar la prueba de autorizacion:", error.message);
  }
}

/* Marca un campo en rojo y pone el motivo debajo.
   Se usa cuando la validacion encuentra un problema. */

function marcarError(idCampo, mensaje) {
  var campo = document.getElementById(idCampo);
  campo.classList.add("campo-error");

  var error = document.createElement("span");
  error.className = "texto-error";
  error.textContent = mensaje;
  campo.parentNode.appendChild(error);
}

/* Muestra un aviso dentro del formulario.
   "tipo" puede ser "ok" (verde) o "error" (rojo). */

function mostrarAviso(texto, tipo) {
  var aviso = document.getElementById("mensajeEnviado");
  aviso.textContent = texto;
  aviso.className = "mensaje-enviado visible " + tipo;
}

/* Envia el formulario al servicio que lo reenvia al correo.
   FormData empaqueta los campos para mandarlos por HTTP.
   fetch() hace la peticion; then() espera la respuesta. */

function enviarFormulario(formulario) {
  var paquete = new FormData(formulario);
  paquete.append("_subject", SITIO.formularioSubject);
  paquete.append("_captcha", "false");
  paquete.append("_template", "table");
  if (paquete.get("correo")) {
    paquete.append("_replyto", paquete.get("correo"));
  }

  return fetch(SITIO.formularioUrl, {
    method: "POST",
    body: paquete,
    headers: { "Accept": "application/json" }
  }).then(function (respuesta) {
    return respuesta.text().then(function (texto) {
      var datos = null;
      try {
        datos = JSON.parse(texto);
      } catch (error) {
        datos = null;
      }
      return { ok: respuesta.ok, datos: datos };
    });
  });
}

/* Dice si la pagina se abrio con doble clic (file://).
   El servicio de correo NO funciona asi: la pagina debe abrirse
   con un servidor web (http://localhost). */

function abiertoComoArchivo() {
  return window.location.protocol === "file:";
}

/* Valida el formulario y lo manda al correo.
   Usa try / catch / throw para manejar los errores. */

function iniciarFormulario() {
  var formulario = document.getElementById("formulario");

  if (!formulario) {
    return;
  }

  var aviso = document.getElementById("mensajeEnviado");

  formulario.addEventListener("submit", function (evento) {
    evento.preventDefault();

    limpiarErrores();
    aviso.style.display = "none";

    try {
      var nombre = document.getElementById("nombre").value.trim();
      var apellido = document.getElementById("apellido").value.trim();
      var correo = document.getElementById("correo").value.trim();
      var telefono = document.getElementById("telefono").value.trim();
      var area = document.getElementById("area").value;
      var textoMensaje = document.getElementById("mensaje").value.trim();
      var privacidad = document.getElementById("privacidad").checked;

      if (nombre === "") {
        throw new Error("nombre");
      }
      if (apellido === "") {
        throw new Error("apellido");
      }
      if (!correoValido(correo)) {
        throw new Error("correo");
      }
      if (area === "") {
        throw new Error("area");
      }
      if (textoMensaje === "") {
        throw new Error("mensaje");
      }
      if (!privacidad) {
        throw new Error("privacidad");
      }

      console.log("Formulario válido. Datos:", {
        nombre: nombre,  /* el nombre de la firma */
        apellido: apellido,
        correo: correo,  /* el correo de la Oficial de proteccion de datos */
        telefono: telefono,  /* el telefono de WhatsApp, como lo ve el visitante */
        area: area,
        mensaje: textoMensaje
      });

      if (abiertoComoArchivo()) {
        mostrarAviso(
          mensaje("formulario.errorArchivo", { telefono: SITIO.telefono }),
          "error"
        );
        return;
      }

      var casillaBoletin = document.getElementById("boletin");
      guardarPruebaAutorizacion({
        fecha: new Date().toLocaleString("es-CO"),  /* la fecha */
        nombre: nombre + " " + apellido,  /* el nombre de la firma */
        correo: correo,  /* el correo de la Oficial de proteccion de datos */
        casillaObligatoria: true,
        casillaBoletin: casillaBoletin ? casillaBoletin.checked : false,
        versionPolitica: SITIO.versionPolitica
      });

      var registro = guardarSolicitud({
        correo: correo,  /* el correo de la Oficial de proteccion de datos */
        telefono: telefono,  /* el telefono de WhatsApp, como lo ve el visitante */
        area: area,
        mensaje: textoMensaje,
        nombre: nombre + " " + apellido,  /* el nombre de la firma */
        tipo: "contacto"
      });

      var boton = formulario.querySelector(".btn-enviar");
      boton.disabled = true;
      boton.textContent = mensaje("formulario.enviando");

      enviarFormulario(formulario)
        .then(function (respuesta) {
          var exito = respuesta.ok;
          if (respuesta.datos && respuesta.datos.success === false) {
            exito = false;
          }

          if (exito) {
            mostrarAviso(
              mensaje("formulario.gracias", { nombre: nombre }),
              "ok"
            );
            registro.estado = "Enviada";
            formulario.reset();
          } else {
            mostrarAviso(
              mensaje("formulario.error", { telefono: SITIO.telefono }),
              "error"
            );
          }
          boton.disabled = false;
          boton.textContent = mensaje("formulario.enviar");
        })
        .catch(function (error) {
          console.log("Error al enviar el formulario:", error.message);
          registro.estado = "Guardada";
          mostrarAviso(
            mensaje("formulario.error", { telefono: SITIO.telefono }),
            "error"
          );
          boton.disabled = false;
          boton.textContent = mensaje("formulario.enviar");
        });
    } catch (error) {
      console.log("Error del formulario:", error.message);
      marcarError(error.message, mensaje("error." + error.message));
    }
  });
}

