/* Activa una animacion suave de aparicion cuando el visitante
   baja por la pagina (scroll). */

function iniciarAnimacionesScroll() {
  if (typeof IntersectionObserver === "undefined") {
    return;
  }

  var elementos = document.querySelectorAll(
    ".titulo-seccion, .bloque-mision, .servicio-card, .abogado-card, .valor-item, .cultura-bloque, .publicacion-card, .area-detalle-bloque, .contacto-info, .formulario, .documento"
  );

  var observador = new IntersectionObserver(
    function (entradas, obs) {
      for (var i = 0; i < entradas.length; i++) {
        if (entradas[i].isIntersecting) {
          entradas[i].target.classList.add("revelado");
          obs.unobserve(entradas[i].target);
        }
      }
    },
    { threshold: 0.12, rootMargin: "0px 0px -30px 0px" }
  );

  for (var j = 0; j < elementos.length; j++) {
    elementos[j].classList.add("revelar-scroll");
    observador.observe(elementos[j]);
  }
}

