/* Punto de partida: dibuja la pagina y hace que los botones y los
   formularios respondan cuando la persona los usa. */
/* =======================================================
   CARRUSEL DE IMAGENES (pagina de inicio)
   -------------------------------------------------------
   Las diapositivas las sube el administrador en el panel
   (datos.carrusel). Solo se dibujan las que tienen imagen.
   Si no hay ninguna, el carrusel no aparece.
   ======================================================= */

var CARRUSEL = [];  /* las diapositivas que se dibujan */
var CARRUSEL_RELOJ = null;  /* el temporizador del avance automatico */

/* Acepta solo enlaces http(s) o rutas internas (por ejemplo contacto.html).
   Bloquea javascript: y cualquier otro esquema. */
function enlaceSeguro(url) {
  if (!url) {
    return "";
  }
  var limpio = String(url).trim();
  if (/^(https?:\/\/[^\s"<>]+|[a-z0-9\-_.\/#?=&%]+)$/i.test(limpio)) {
    return escaparTexto(limpio);
  }
  return "";
}

function crearCarrusel() {
  if (!CARRUSEL.length) {
    return "";
  }

  var diapositivas = "";
  var puntos = "";

  for (var i = 0; i < CARRUSEL.length; i++) {
    var d = CARRUSEL[i];
    var titulo = escaparTexto(d.titulo || "");
    var tituloEn = escaparTexto(d.tituloEn || d.titulo || "");
    var texto = escaparTexto(d.texto || "");
    var textoEn = escaparTexto(d.textoEn || d.texto || "");
    var enlace = enlaceSeguro(d.enlace);
    var boton = enlace
      ? '<a class="btn-banner btn-borde carrusel-boton" href="' + enlace + '">' +
        '<span class="es">Ver más</span><span class="en">Learn more</span></a>'
      : "";

    diapositivas +=
      '<figure class="carrusel-diapositiva' + (i === 0 ? " activa" : "") + '" data-indice="' + i + '">' +
        '<img src="' + escaparTexto(d.imagen) + '" alt="' + titulo + '" loading="lazy">' +
        '<figcaption class="carrusel-texto">' +
          '<strong><span class="es">' + titulo + '</span><span class="en">' + tituloEn + '</span></strong>' +
          '<span class="es">' + texto + '</span><span class="en">' + textoEn + '</span>' +
          boton +
        '</figcaption>' +
      '</figure>';

    puntos += '<button type="button" class="carrusel-punto' + (i === 0 ? " activo" : "") +
      '" data-indice="' + i + '" aria-label="Diapositiva ' + (i + 1) + ' / Slide ' + (i + 1) + '"></button>';
  }

  var controles = "";
  if (CARRUSEL.length > 1) {
    controles =
      '<button type="button" class="carrusel-control carrusel-ant" aria-label="Anterior / Previous">&#8249;</button>' +
      '<button type="button" class="carrusel-control carrusel-sig" aria-label="Siguiente / Next">&#8250;</button>' +
      '<div class="carrusel-puntos">' + puntos + '</div>';
  }

  return '<section class="carrusel" id="carrusel" aria-roledescription="carrusel" ' +
    'aria-label="Destacados / Highlights">' +
    '<div class="carrusel-pista">' + diapositivas + '</div>' + controles +
    '</section>';
}

function detenerCarrusel() {
  if (CARRUSEL_RELOJ) {
    clearInterval(CARRUSEL_RELOJ);
    CARRUSEL_RELOJ = null;
  }
}

/* Activa el carrusel: avance automatico cada 6 segundos (se pausa al
   pasar el mouse o el foco, y no avanza si el visitante pide menos
   movimiento), botones, puntos, teclas de flecha y deslizar en el celular. */
function iniciarCarrusel() {
  detenerCarrusel();

  var carrusel = document.getElementById("carrusel");
  if (!carrusel) {
    return;
  }

  var diapositivas = carrusel.querySelectorAll(".carrusel-diapositiva");
  var puntos = carrusel.querySelectorAll(".carrusel-punto");
  var total = diapositivas.length;
  var actual = 0;
  var pausado = false;
  var sinMovimiento = window.matchMedia &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  if (total < 2) {
    return;
  }

  function mostrar(indice) {
    actual = (indice + total) % total;
    for (var i = 0; i < total; i++) {
      var activa = i === actual;
      diapositivas[i].classList.toggle("activa", activa);
      diapositivas[i].setAttribute("aria-hidden", activa ? "false" : "true");
      if (puntos[i]) {
        puntos[i].classList.toggle("activo", activa);
        puntos[i].setAttribute("aria-current", activa ? "true" : "false");
      }
    }
  }

  function arrancar() {
    detenerCarrusel();
    if (!pausado && !sinMovimiento) {
      CARRUSEL_RELOJ = setInterval(function () { mostrar(actual + 1); }, 6000);
    }
  }

  function manual(indice) {
    mostrar(indice);
    arrancar();
  }

  carrusel.querySelector(".carrusel-ant").addEventListener("click", function () { manual(actual - 1); });
  carrusel.querySelector(".carrusel-sig").addEventListener("click", function () { manual(actual + 1); });

  for (var p = 0; p < puntos.length; p++) {
    puntos[p].addEventListener("click", function (evento) {
      manual(parseInt(evento.currentTarget.getAttribute("data-indice"), 10));
    });
  }

  carrusel.addEventListener("mouseenter", function () { pausado = true; detenerCarrusel(); });
  carrusel.addEventListener("mouseleave", function () { pausado = false; arrancar(); });
  carrusel.addEventListener("focusin", function () { pausado = true; detenerCarrusel(); });
  carrusel.addEventListener("focusout", function () { pausado = false; arrancar(); });

  carrusel.addEventListener("keydown", function (evento) {
    if (evento.key === "ArrowLeft") { manual(actual - 1); }
    if (evento.key === "ArrowRight") { manual(actual + 1); }
  });

  var inicioX = null;
  carrusel.addEventListener("touchstart", function (evento) {
    inicioX = evento.touches[0].clientX;
  }, { passive: true });
  carrusel.addEventListener("touchend", function (evento) {
    if (inicioX === null) { return; }
    var dx = evento.changedTouches[0].clientX - inicioX;
    inicioX = null;
    if (Math.abs(dx) > 40) { manual(actual + (dx < 0 ? 1 : -1)); }
  });

  arrancar();
}


